/*
 * microWakeWord engine host test.
 *
 * Feeds the LibreEcho Alexa e2e fixtures plus one real "Okay Nabu" clip,
 * repo-relative tests/fixtures/okay_nabu_turn_on_the_lights.wav, resolved
 * from the fixture directory given on the command line.
 * Audio goes through the engine in
 * 10 ms chunks, so every 30 ms inference produces one score, and compares
 * every sliding-window mean with the values generated by
 * tests/gen_wake_engine_mww_expected.py from pymicro-wakeword 2.5.0.
 */

#include "adapter/wake_engine.h"

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <map>
#include <string>
#include <utility>
#include <vector>

namespace {

constexpr std::size_t kChunkSamples = 160;  /* one 10 ms feature row */
/* All comparisons hold pymicro-wakeword to 1/255 except alexa-twice.  Its
 * quantized int8 inputs were byte-identical at every differing step, but 3 of
 * 370 raw outputs differ by up to 7 LSB because TFLM and the pymicro TFLite
 * host runtime round kernels differently, and the sigmoid transition amplifies
 * that; the first sliding-mean deviation is step 288 (0.220312506 vs
 * 0.214843750). */
constexpr float kTolerance = 1.0f / 255.0f;
constexpr float kTflmRuntimeTolerance = 8.0f / 255.0f;

uint16_t read_u16(const unsigned char *p)
{
    return static_cast<uint16_t>(
        static_cast<uint16_t>(p[0]) |
        static_cast<uint16_t>(p[1]) << 8);
}

uint32_t read_u32(const unsigned char *p)
{
    return static_cast<uint32_t>(p[0]) |
           static_cast<uint32_t>(p[1]) << 8 |
           static_cast<uint32_t>(p[2]) << 16 |
           static_cast<uint32_t>(p[3]) << 24;
}

bool load_wav(const char *path, std::vector<int16_t> *samples)
{
    std::ifstream input(path, std::ios::binary);
    std::vector<unsigned char> bytes(
        (std::istreambuf_iterator<char>(input)),
        std::istreambuf_iterator<char>());
    std::size_t offset = 12;
    bool format_ok = false;

    if (bytes.size() < 12 ||
        std::memcmp(bytes.data(), "RIFF", 4) != 0 ||
        std::memcmp(bytes.data() + 8, "WAVE", 4) != 0)
        return false;
    while (offset + 8 <= bytes.size()) {
        const unsigned char *header = bytes.data() + offset;
        const std::size_t size = read_u32(header + 4);
        const std::size_t data_offset = offset + 8;

        if (data_offset + size > bytes.size())
            return false;
        if (std::memcmp(header, "fmt ", 4) == 0) {
            if (size < 16 ||
                read_u16(bytes.data() + data_offset) != 1 ||
                read_u16(bytes.data() + data_offset + 2) != 1 ||
                read_u32(bytes.data() + data_offset + 4) != 16000 ||
                read_u16(bytes.data() + data_offset + 14) != 16)
                return false;
            format_ok = true;
        } else if (std::memcmp(header, "data", 4) == 0) {
            if (!format_ok || size % sizeof(int16_t) != 0)
                return false;
            samples->resize(size / sizeof(int16_t));
            for (std::size_t i = 0; i < samples->size(); ++i)
                (*samples)[i] =
                    static_cast<int16_t>(
                        read_u16(bytes.data() + data_offset + i * 2));
            return true;
        }
        offset = data_offset + size + (size & 1U);
    }
    return false;
}

using Expected = std::map<std::pair<std::string, std::string>,
                          std::vector<float>>;

bool load_expected(const char *path, Expected *expected)
{
    std::ifstream input(path);
    std::string line;
    unsigned int line_number = 0;

    if (!input)
        return false;
    while (std::getline(input, line)) {
        char model[64];
        char clip[64];
        unsigned int step = 0;
        float probability = 0.0f;

        ++line_number;
        if (line.empty() || line[0] == '#')
            continue;
        if (std::sscanf(line.c_str(), "%63s %63s %u %f", model, clip, &step,
                        &probability) != 4) {
            std::fprintf(stderr, "bad expected line %u: %s\n", line_number,
                         line.c_str());
            return false;
        }
        std::vector<float> &values =
            (*expected)[std::make_pair(std::string(model), std::string(clip))];

        if (values.size() <= step)
            values.resize(step + 1, 0.0f);
        values[step] = probability;
    }
    return true;
}

bool run_clip(const char *models, const char *model, const char *clip,
              const char *wav, const std::vector<float> &expected)
{
    std::vector<int16_t> samples;
    le_wake_engine *engine;
    std::size_t step = 0;
    std::size_t mismatches = 0;
    float max_vad = 0.0f;
    float tolerance = kTolerance;
    float max_deviation = 0.0f;
    std::size_t max_deviation_step = 0;
    float max_deviation_engine = 0.0f;
    float max_deviation_expected = 0.0f;

    if (std::strcmp(model, "alexa") == 0 &&
        std::strcmp(clip, "alexa-twice") == 0)
        tolerance = kTflmRuntimeTolerance;

    if (!load_wav(wav, &samples)) {
        std::fprintf(stderr, "unable to read 16 kHz mono PCM16 WAV: %s\n",
                     wav);
        return false;
    }
    const std::string directory =
        std::string(models) + "/" + model;
    engine = le_wake_engine_create(directory.c_str(), 1);
    if (!engine) {
        std::fprintf(stderr, "engine did not load %s\n", directory.c_str());
        return false;
    }
    for (std::size_t offset = 0;
         offset + kChunkSamples <= samples.size();
         offset += kChunkSamples) {
        float score = 0.0f;
        int new_score = 0;

        if (le_wake_engine_feed(engine, samples.data() + offset,
                                kChunkSamples, &score, &new_score) < 0) {
            std::fprintf(stderr, "%s %s: inference failed at step %zu\n",
                         model, clip, step);
            le_wake_engine_destroy(engine);
            return false;
        }
        max_vad = std::max(max_vad, le_wake_engine_vad_score(engine));
        if (!new_score)
            continue;
        if (step >= expected.size()) {
            std::fprintf(stderr, "%s %s: unexpected step %zu\n",
                         model, clip, step);
            le_wake_engine_destroy(engine);
            return false;
        }
        const float deviation = std::fabs(score - expected[step]);

        if (deviation > max_deviation) {
            max_deviation = deviation;
            max_deviation_step = step;
            max_deviation_engine = score;
            max_deviation_expected = expected[step];
        }
        if (deviation > tolerance) {
            if (mismatches == 0) {
                std::fprintf(stderr,
                             "%s %s: first mismatch at step %zu"
                             " (feature rows=3): engine=%.9f expected=%.9f\n",
                             model, clip, step, score, expected[step]);
            }
            ++mismatches;
        }
        ++step;
    }
    const unsigned int inference_us =
        le_wake_engine_last_inference_us(engine);

    le_wake_engine_destroy(engine);
    if (step != expected.size()) {
        std::fprintf(stderr, "%s %s: engine produced %zu steps, expected %zu\n",
                     model, clip, step, expected.size());
        return false;
    }
    if (mismatches != 0) {
        std::fprintf(stderr,
                     "%s %s: %zu of %zu steps differ; max deviation %.9f"
                     " at step %zu (engine=%.9f expected=%.9f)\n",
                     model, clip, mismatches, step, max_deviation,
                     max_deviation_step, max_deviation_engine,
                     max_deviation_expected);
        return false;
    }
    if (max_vad <= 0.0f || max_vad > 1.0f) {
        std::fprintf(stderr, "%s %s: VAD score out of range: %.9f\n",
                     model, clip, max_vad);
        return false;
    }
    std::printf("PASS %s %s steps=%zu max_step_tolerance=%.9f"
                " max_deviation=%.9f max_vad=%.4f max_inference_us=%u\n",
                model, clip, step, tolerance, max_deviation, max_vad,
                inference_us);
    return true;
}

}  // namespace

int main(int argc, char **argv)
{
    if (argc != 4) {
        std::fprintf(stderr,
                     "Usage: %s MODEL_ROOT FIXTURE_DIR EXPECTED.txt\n",
                     argv[0]);
        return 2;
    }
    Expected expected;

    if (!load_expected(argv[3], &expected)) {
        std::fprintf(stderr, "unable to read %s\n", argv[3]);
        return 2;
    }
    const char *models[] = {"alexa", "okay_nabu"};
    const char *clips[] = {"alexa-what-time", "alexa-twice", "okay-nabu"};
    bool ok = true;

    for (const char *model : models) {
        for (const char *clip : clips) {
            const auto key = std::make_pair(std::string(model),
                                            std::string(clip));
            const auto found = expected.find(key);
            std::string wav = std::string(argv[2]) +
                              "/voice-e2e/fixtures/" + clip + ".wav";

            if (std::strcmp(clip, "okay-nabu") == 0)
                wav = std::string(argv[2]) +
                      "/fixtures/okay_nabu_turn_on_the_lights.wav";
            if (found == expected.end()) {
                std::fprintf(stderr, "no expected values for %s %s\n",
                             model, clip);
                ok = false;
                continue;
            }
            if (!run_clip(argv[1], model, clip, wav.c_str(), found->second))
                ok = false;
        }
    }
    return ok ? 0 : 1;
}
